    const last = el.path.at(-1);
    const prev = el.path.at(-2);
    const dir = norm(sub(last, prev));
    const fr = new Frame(last, Math.atan2(dir[1], dir[0]), z);
    frameBox(b, fr, -bw, -bw / 2, 0, 0, bw / 2, H - r, col);
