function elevationViews(doc, center = [0, 0], radius = 14000) {
  const imp = doc.units.system === 'imperial';
  const s = imp ? 96 : 100;
  const mk = (name, origin, look) => ({ id: newId('v'), kind: 'elevation', name, origin, look, scale: s, width: 40000, ...VIEW_DEFAULTS.elevation });
  return [
    mk('Norte', [center[0], center[1] + radius], -Math.PI / 2),
    mk('Leste', [center[0] + radius, center[1]], Math.PI),
    mk('Sul', [center[0], center[1] - radius], Math.PI / 2),
    mk('Oeste', [center[0] - radius, center[1]], 0),
  ];
}

function default3DView(name = 'Vista 3D') {
  return {
    id: newId('v'),
    kind: 'view3d',
    name,
    camera: { target: [6000, 4000, 1500], dist: 32000, yaw: -0.85, pitch: 0.55, persp: true, fov: 45 },
    ...VIEW_DEFAULTS.view3d,
  };
}

