  door: (g, n, p, r, tag, el, ctx) => `IFCDOOR('${g}',$,${n},$,$,${p},${r},${tag},${num(ctx.size(el).height)},${num(ctx.size(el).width)},.DOOR.,.NOTDEFINED.,$)`,
